INSERT INTO `newsletter_templates` (`id`, `name`, `description`, `preview_image`, `html_content`, `variables`, `category`, `is_active`, `created_at`) VALUES
(1, 'Welcome Email', 'Friendly welcome message for new subscribers', NULL, '<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;background:#000;color:#fff;padding:40px\"><h1 style=\"color:#ff1493;text-align:center\">WELCOME TO EESOME!</h1><p>Hi {name},</p><p>Thank you for joining our community!</p><a href=\"https://eesomebd.store/shop.php\" style=\"background:#ff1493;color:#fff;padding:15px 40px;text-decoration:none;display:inline-block;border-radius:30px\">START SHOPPING</a></div>', NULL, 'onboarding', 1, '2025-12-24 11:42:14'),
(2, 'Product Launch', 'Announce new product arrivals', NULL, '<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;background:#000;color:#fff;padding:40px\"><h1 style=\"color:#ff1493;text-align:center\">NEW ARRIVAL!</h1><p>Hi {name},</p><p>Check out our latest: {product_name}</p><p style=\"color:#ff1493;font-size:28px\">{product_price}</p><a href=\"{product_link}\" style=\"background:#ff1493;color:#fff;padding:15px 40px;text-decoration:none;display:inline-block;border-radius:30px\">SHOP NOW</a></div>', NULL, 'promotions', 1, '2025-12-24 11:42:14'),
(3, 'Sale Promotion', 'Announce sales and special offers', NULL, '<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;background:#000;color:#fff;padding:40px\"><h1 style=\"color:#ff1493;text-align:center;font-size:56px\">FLASH SALE</h1><h2 style=\"text-align:center\">UP TO {discount_percent}% OFF!</h2><p>Hi {name},</p><div style=\"background:#ff1493;color:#fff;padding:20px;text-align:center;font-size:24px;border-radius:10px\">{coupon_code}</div><a href=\"https://eesomebd.store/shop.php\" style=\"background:#ff1493;color:#fff;padding:20px 60px;text-decoration:none;display:inline-block;border-radius:30px;margin-top:30px\">SHOP NOW</a></div>', NULL, 'promotions', 1, '2025-12-24 11:42:14'),
(4, 'Newsletter Digest', 'Weekly or monthly updates', NULL, '<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;background:#000;color:#fff;padding:40px\"><h1 style=\"color:#ff1493\">This Week at EEsome</h1><p>Hi {name},</p><h3>Featured This Week</h3><p>{featured_content}</p><h3>Latest Articles</h3><p><a href=\"{blog_link_1}\" style=\"color:#ff1493\">{blog_title_1}</a></p><a href=\"https://eesomebd.store\" style=\"background:#ff1493;color:#fff;padding:15px 40px;text-decoration:none;display:inline-block;border-radius:30px\">VISIT EESOME</a></div>', NULL, 'general', 1, '2025-12-24 11:42:14'),
(5, 'Event Invitation', 'Invitations for special events', NULL, '<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;background:#000;color:#fff;padding:40px;border:2px solid #ff1493\"><h1 style=\"color:#fff;text-align:center\">{event_name}</h1><p>Hi {name}, you are invited!</p><p>Date: {event_date}</p><p>Time: {event_time}</p><p>Location: {event_location}</p><a href=\"{rsvp_link}\" style=\"background:#ff1493;color:#fff;padding:18px 50px;text-decoration:none;display:inline-block;border-radius:30px\">RSVP NOW</a></div>', NULL, 'events', 1, '2025-12-24 11:42:14');
